/**
 * POST /nodes/{node}/lxc/{vmid}/mtunnel
 * Migration tunnel endpoint - only for internal use by CT migration.
 * Path variables: node, vmid
 */
export interface NodesLxcMtunnelPostParams {
	/**
	 * List of network bridges to check availability. Will be checked again for actually used bridges during migration.
	 * Format: pve-bridge-id-list
	 */
	bridges?: string
	/**
	 * List of storages to check permission and availability. Will be checked again for all actually used storages during migration.
	 * Format: pve-storage-id-list
	 */
	storages?: string
}

/**
 * POST /nodes/{node}/lxc/{vmid}/remote_migrate
 * Migrate the container to another cluster. Creates a new migration task. EXPERIMENTAL feature!
 * Path variables: node, vmid
 */
export interface NodesLxcRemoteMigratePostParams {
	/**
	 * Override I/O bandwidth limit (in KiB/s).
	 * Default: "migrate limit from datacenter or storage config"
	 * Range: 0 to -
	 */
	bwlimit?: number
	/**
	 * Delete the original CT and related data after successful migration. By default the original CT is kept on the source cluster in a stopped state.
	 * Default: 0
	 */
	delete?: boolean
	/** Use online/live migration. */
	online?: boolean
	/** Use restart migration */
	restart?: boolean
	/**
	 * Mapping from source to target bridges. Providing only a single bridge ID maps all source bridges to that bridge. Providing the special value '1' will map each source bridge to itself.
	 * Format: bridge-pair-list
	 */
	"target-bridge": string
	/**
	 * Remote target endpoint
	 * Format: proxmox-remote
	 */
	"target-endpoint": string
	/**
	 * Mapping from source to target storages. Providing only a single storage ID maps all source storages to that storage. Providing the special value '1' will map each source storage to itself.
	 * Format: storage-pair-list
	 */
	"target-storage": string
	/**
	 * The (unique) ID of the VM.
	 * Format: pve-vmid
	 * Range: 100 to 999999999
	 */
	"target-vmid"?: number
	/**
	 * Timeout in seconds for shutdown for restart migration
	 * Default: 180
	 */
	timeout?: number
}

/**
 * POST /nodes/{node}/lxc/{vmid}/snapshot
 * Snapshot a container.
 * Path variables: node, vmid
 */
export interface NodesLxcSnapshotPostParams {
	/** A textual description or comment. */
	description?: string
	/**
	 * The name of the snapshot.
	 * Format: pve-configid
	 */
	snapname: string
}

/**
 * POST /nodes/{node}/lxc/{vmid}/snapshot/{snapname}/rollback
 * Rollback LXC state to specified snapshot.
 * Path variables: node, vmid, snapname
 */
export interface NodesLxcSnapshotRollbackPostParams {
	/**
	 * Whether the container should get started after rolling back successfully
	 * Default: 0
	 */
	start?: boolean
}

/**
 * POST /nodes/{node}/lxc/{vmid}/spiceproxy
 * Returns a SPICE configuration to connect to the CT.
 * Path variables: node, vmid
 */
export interface NodesLxcSpiceproxyPostParams {
	/**
	 * SPICE proxy server. This can be used by the client to specify the proxy server. All nodes in a cluster runs 'spiceproxy', so it is up to the client to choose one. By default, we return the node where...
	 * Format: address
	 */
	proxy?: string
}

/**
 * POST /nodes/{node}/lxc/{vmid}/status/reboot
 * Reboot the container by shutting it down, and starting it again. Applies pending changes.
 * Path variables: node, vmid
 */
export interface NodesLxcStatusRebootPostParams {
	/**
	 * Wait maximal timeout seconds for the shutdown.
	 * Range: 0 to -
	 */
	timeout?: number
}

/**
 * POST /nodes/{node}/lxc/{vmid}/status/resume
 * Resume the container.
 * Path variables: node, vmid
 */
export interface NodesLxcStatusResumePostParams {}

/**
 * POST /nodes/{node}/lxc/{vmid}/status/shutdown
 * Shutdown the container. This will trigger a clean shutdown of the container, see lxc-stop(1) for details.
 * Path variables: node, vmid
 */
export interface NodesLxcStatusShutdownPostParams {
	/**
	 * Make sure the Container stops.
	 * Default: 0
	 */
	forceStop?: boolean
	/**
	 * Wait maximal timeout seconds.
	 * Default: 60
	 * Range: 0 to -
	 */
	timeout?: number
}

/**
 * POST /nodes/{node}/lxc/{vmid}/status/start
 * Start the container.
 * Path variables: node, vmid
 */
export interface NodesLxcStatusStartPostParams {
	/**
	 * If set, enables very verbose debug log-level on start.
	 * Default: 0
	 */
	debug?: boolean
	/** Ignore locks - only root is allowed to use this option. */
	skiplock?: boolean
}

/**
 * POST /nodes/{node}/lxc/{vmid}/status/stop
 * Stop the container. This will abruptly stop all processes running in the container.
 * Path variables: node, vmid
 */
export interface NodesLxcStatusStopPostParams {
	/**
	 * Try to abort active 'vzshutdown' tasks before stopping.
	 * Default: 0
	 */
	"overrule-shutdown"?: boolean
	/** Ignore locks - only root is allowed to use this option. */
	skiplock?: boolean
}

/**
 * POST /nodes/{node}/lxc/{vmid}/status/suspend
 * Suspend the container. This is experimental.
 * Path variables: node, vmid
 */
export interface NodesLxcStatusSuspendPostParams {}

/**
 * POST /nodes/{node}/lxc/{vmid}/template
 * Create a Template.
 * Path variables: node, vmid
 */
